@push('scripts')@include('partials.import-poll')<script>
document.addEventListener('click',function(e){var b=e.target.closest('.delete-designation-btn');if(b){document.getElementById('delete_designation_form').action=b.dataset.url;document.getElementById('delete_designation_message').textContent='Are you sure you want to delete "'+b.dataset.name+'"?';}});
function applyDesignationFilter(status){fetch('{{ url('employee-structure/designations/filter') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({status:status})}).then(function(r){return r.json();}).then(function(data){var table=document.querySelector('table.datatable');var sourceBody=table.querySelector('tbody');var rowContainer=document.createElement('tbody');var visibleBody=document.querySelector('.gridjs-tbody');rowContainer.innerHTML=data.html;sourceBody.innerHTML=data.html;if(visibleBody){visibleBody.innerHTML='';rowContainer.querySelectorAll('tr').forEach(function(row){row.classList.add('gridjs-tr');row.querySelectorAll('td').forEach(function(cell){cell.classList.add('gridjs-td');});visibleBody.appendChild(row);});}var pages=document.querySelector('.gridjs-pages');if(pages){pages.innerHTML='';}}).catch(function(error){console.error('Filter error:',error);});}
document.querySelectorAll('.designation-status-filter').forEach(function(b){b.addEventListener('click',function(){applyDesignationFilter(this.dataset.status);});});
</script>@endpush
